def reprendre_client_des_commandes(apps, schema_editor):
    """Le client d'une facture existante est celui de sa commande. Nom et adresse imprimés restent vides : ils sont alors
    repris de la fiche à l'impression (une facture déjà émise ne change pas)."""
    Facture = apps.get_model("facturation", "Facture")
    for facture in Facture.objects.filter(client__isnull=True, commande__isnull=False).select_related("commande"):
        Facture.objects.filter(pk=facture.pk).update(client_id=facture.commande.client_id)


